const tearErosionMap = {
  "slight fray": 0.1,
  "creeping breach": 0.25,
  "ragged fissure": 0.4,
  "cavernous tear": 0.6,
  "total disintegration": 0.8,
  "catastrophic chasm": 0.95
};

const anchorDensityMap = {
  "sparse basting": 16,
  "spaced tacking": 24,
  "continuous seam": 36,
  "overlocked hem": 48,
  "dense suture lattice": 60,
  "swarming needlepoint": 72
};

const bridgeReachMap = {
  "short cross-stitches": 60,
  "taut spans": 120,
  "reaching gussets": 200,
  "vaulting braces": 350,
  "abyssal leaps": 500,
  "void spanning cables": 800
};

const threadTensionMap = {
  "slack cord": 0.5,
  "drawn twine": 1,
  "plucked wire": 2.5,
  "furious jitter": 5,
  "harmonic spasm": 8,
  "resonant frenzy": 12
};

const chromaTemperMap = {
  "indigo on raw linen": { void: '#0f172a', fabric: '#e2dcd0', thread: '#1e3a8a', snap: '#64748b', margin: '#94a3b8' },
  "cobalt and bone": { void: '#001a33', fabric: '#f4f0ec', thread: '#0047b3', snap: '#6699cc', margin: '#a3b1c6' },
  "charcoal with chalk": { void: '#111111', fabric: '#2a2a2a', thread: '#e0e0e0', snap: '#999999', margin: '#000000' },
  "oxblood on vellum": { void: '#2a0808', fabric: '#e8ddcb', thread: '#8a1111', snap: '#cc5252', margin: '#3d1a1a' },
  "electric cyan on obsidian": { void: '#000000', fabric: '#0d0d0d', thread: '#00ffff', snap: '#00b3b3', margin: '#003333' },
  "verdigris and scorched lead": { void: '#1f2422', fabric: '#363636', thread: '#409c85', snap: '#7aa397', margin: '#141a18' }
};

p.setup = function() {
  p.createCanvas(800, 800);
};

p.draw = function() {
  const erosionKey = p.getSynthVar('tear_erosion') || "slight fray";
  const densityKey = p.getSynthVar('anchor_density') || "sparse basting";
  const reachKey = p.getSynthVar('bridge_reach') || "short cross-stitches";
  const tensionKey = p.getSynthVar('thread_tension') || "slack cord";
  const chromaKey = p.getSynthVar('chroma_temper') || "indigo on raw linen";

  const erosion = tearErosionMap[erosionKey];
  const density = anchorDensityMap[densityKey];
  const reach = bridgeReachMap[reachKey];
  const tension = threadTensionMap[tensionKey];
  const chroma = chromaTemperMap[chromaKey];

  p.background(chroma.void);

  let pts = [];
  for (let i = 0; i < density; i++) {
    let angle = (i * p.TWO_PI) / density;
    let nVal = p.noise(p.cos(angle) + 2, p.sin(angle) + 2, p.frameCount * 0.005);
    let r = 120 + erosion * 140 + nVal * erosion * 120;
    r = p.min(380, r);
    let x = 400 + p.cos(angle) * r;
    let y = 400 + p.sin(angle) * r;

    x += (p.random() - 0.5) * tension;
    y += (p.random() - 0.5) * tension;
    pts.push({ x, y });
  }

  p.fill(chroma.fabric);
  p.stroke(chroma.margin);
  p.strokeWeight(6);
  p.beginShape();
  p.vertex(0, 0);
  p.vertex(800, 0);
  p.vertex(800, 800);
  p.vertex(0, 800);
  p.beginContour();
  for (let i = pts.length - 1; i >= 0; i--) {
    p.vertex(pts[i].x, pts[i].y);
  }
  p.endContour();
  p.endShape(p.CLOSE);

  p.stroke(chroma.thread);
  p.strokeWeight(1.2);
  p.noFill();
  p.beginShape(p.LINES);
  let snaps = [];

  for (let i = 0; i < pts.length; i++) {
    let linked = 0;
    for (let offset = 2; offset < pts.length / 2; offset++) {
      let j = (i + offset) % pts.length;
      if (i >= j) continue; 

      if ((i * 11 + j * 13) % 10 < 3) {
        let dx = pts[i].x - pts[j].x;
        let dy = pts[i].y - pts[j].y;
        let dist = p.mag(dx, dy);

        if (dist <= reach) {
          p.vertex(pts[i].x, pts[i].y);
          p.vertex(pts[j].x, pts[j].y);
          linked++;
        } else {
          if (snaps.length < 40) snaps.push([pts[i], pts[j], dist]);
        }
        if (linked >= 3) break;
      }
    }
  }
  p.endShape();

  p.stroke(chroma.snap);
  p.strokeWeight(1.5);
  for (let s = 0; s < snaps.length; s++) {
    let pt1 = snaps[s][0];
    let pt2 = snaps[s][1];
    drawSpring(pt1, pt2, tension);
    drawSpring(pt2, pt1, tension);
  }

  p.stroke(chroma.thread);
  p.strokeWeight(3.5);
  p.beginShape(p.POINTS);
  for (let i = 0; i < pts.length; i++) {
    p.vertex(pts[i].x, pts[i].y);
  }
  p.endShape();

  function drawSpring(p1, p2, tens) {
    p.beginShape();
    let dx = p2.x - p1.x;
    let dy = p2.y - p1.y;
    let dist = p.mag(dx, dy);
    let ux = dx / dist;
    let uy = dy / dist;
    let maxL = p.min(dist * 0.25, 40 + tens * 2);
    let steps = 8;

    p.vertex(p1.x, p1.y);
    for (let i = 1; i <= steps; i++) {
      let t = i / steps;
      let bx = p1.x + ux * maxL * t;
      let by = p1.y + uy * maxL * t;
      let px = -uy;
      let py = ux;
      let amp = (i % 2 === 0 ? 1 : -1) * (4 + tens * 0.8);
      let jit = (p.noise(p1.x, i, p.frameCount * 0.15) - 0.5) * tens * 3;
      p.vertex(bx + px * amp + px * jit, by + py * amp + py * jit);
    }
    p.endShape();
  }
};
